package com.chatsystem.admin.controller;
import com.chatsystem.admin.navigation.*;import com.chatsystem.admin.ui.cell.AdminGroupCell;import com.chatsystem.shared.model.Conversation;import com.chatsystem.shared.service.AdminService;import javafx.collections.*;import javafx.fxml.FXML;import javafx.scene.control.*;import java.util.*;
public final class GroupsController implements DisposableController{
 private final AdminService service;private final AdminNavigator navigator;private final ObservableList<Conversation> results=FXCollections.observableArrayList();private final javafx.beans.InvalidationListener refreshListener=o->refresh();private String query="";private AdminService.GroupSort sort=AdminService.GroupSort.MEMBER_COUNT;@FXML private TextField searchField;@FXML private ListView<Conversation> groupList;@FXML private Label emptyLabel,totalMetric,membersMetric,flaggedMetric;@FXML private MenuButton sortButton;
 public GroupsController(AdminService s,AdminNavigator n){service=s;navigator=n;service.getGroups().addListener(refreshListener);refresh();}@FXML private void initialize(){searchField.textProperty().addListener((o,a,b)->setQuery(b));groupList.setItems(results);groupList.setCellFactory(v->new AdminGroupCell(service,this::open));for(var value:AdminService.GroupSort.values()){MenuItem item=new MenuItem(value.name().toLowerCase().replace('_',' '));item.setOnAction(e->setSort(value));sortButton.getItems().add(item);}refresh();}
 public ObservableList<Conversation> results(){return FXCollections.unmodifiableObservableList(results);}public void setQuery(String q){query=q==null?"":q;refresh();}public void setSort(AdminService.GroupSort s){sort=Objects.requireNonNull(s);refresh();}public void open(long id){navigator.navigate(ViewRequest.group(id));}private void refresh(){if(totalMetric!=null){totalMetric.setText(Integer.toString(service.getGroups().size()));membersMetric.setText(Integer.toString(service.getGroups().stream().mapToInt(g->service.getGroupMembers(g.getId()).size()).sum()));flaggedMetric.setText(Long.toString(service.getGroups().stream().filter(g->!service.searchReportsForConversation(g.getId(),"",null,com.chatsystem.shared.service.ReportService.ReportSort.NEWEST,0,1).isEmpty()).count()));}results.setAll(service.searchGroups(query,sort,0,50));if(sortButton!=null)sortButton.setText("Sort: "+sort.name().toLowerCase().replace('_',' '));if(emptyLabel!=null){emptyLabel.setVisible(results.isEmpty());emptyLabel.setManaged(results.isEmpty());}}
 public void dispose(){service.getGroups().removeListener(refreshListener);}
}
